render(env) {
    const { W, H, sc } = env, p = env.cut.params, u = U(env);
    const chars = hasLatin(env.cut.text) ? [...env.cut.text.trim().replace(/\s+/g, ' ')] : [...strip(env.cut.text)], n = chars.length;
    const v = p.orient === 'v';
