    const endY = -R * Math.cos(half) + size * 0.55;
    const capY = hollow ? Math.max(0, -R * Math.cos(half) - R * 0.1) : endY + ls * 1.6;
    const botOff = Math.max(endY, capY + ls * 2.2);
