      hy = top + kickH + m.h / 2; ry = hy + m.h / 2 + size * 0.22; dy = ry + ls * 1.2;
    }
    // kicker
    const ka = tin(env, 0.05, 0.4) * out;
    const ky = hy - m.h / 2 - ls * 1.1;
