      bb = J.mainDraw(env, { text: fb.text, font: p.font, size, x: m + hbw / 2, y: m + hbh / 2, lead: 1.05, track: -0.02, color: rev ? C.fill : tx, noHold: plateHold(env), mi: miAt(env, p.spin ? 0.45 : 0.3) });
