    const slC = p.sleeve === 'card' ? card(sc).fill : plateCol(sc, p.sleeve === 'accent' ? [sc.accent, sc.ink] : [sc.ink, sc.fg]);
    const tc = onCol(sc, slC);
    const x0 = sx - S / 2 + (port ? 0 : off), y0 = sy - S / 2 + (port ? off : 0);
